 1	import java.util.ArrayDeque;
 2	import java.util.ArrayList;
 3	import java.util.Deque;
 4	import java.util.List;
 5	
 6	public class DepthFirstSearch {
 7	
 8	    private DepthFirstSearch() {
 9	    }
10	
11	    public static List<Integer> dfs(List<List<Integer>> adjacencyList) {
12	        validateAdjacencyList(adjacencyList);
13	
14	        boolean[] visitedVertices = new boolean[adjacencyList.size()];
15	        List<Integer> traversalOrder = new ArrayList<>();
16	
17	        for (int vertex = 0; vertex < adjacencyList.size(); vertex++) {
18	            if (!visitedVertices[vertex]) {
19	                traverseComponent(adjacencyList, visitedVertices, vertex, traversalOrder);
20	            }
21	        }
22	
23	        return traversalOrder;
24	    }
25	
26	    private static void validateAdjacencyList(List<List<Integer>> adjacencyList) {
27	        if (adjacencyList == null) {
28	            throw new IllegalArgumentException("adjacencyList must not be null");
29	        }
30	
31	        int vertexCount = adjacencyList.size();
32	        for (int vertex = 0; vertex < vertexCount; vertex++) {
33	            List<Integer> neighbors = adjacencyList.get(vertex);
34	            if (neighbors == null) {
35	                throw new IllegalArgumentException("Neighbors for vertex " + vertex + " must not be null");
36	            }
37	
38	            for (Integer neighbor : neighbors) {
39	                if (neighbor == null) {
40	                    throw new IllegalArgumentException("Neighbor for vertex " + vertex + " must not be null");
41	                }
42	                if (neighbor < 0 || neighbor >= vertexCount) {
43	                    throw new IllegalArgumentException(
44	                            "Neighbor " + neighbor + " for vertex " + vertex + " is outside the graph");
45	                }
46	            }
47	        }
48	    }
49	
50	    private static void traverseComponent(
51	            List<List<Integer>> adjacencyList,
52	            boolean[] visitedVertices,
53	            int startVertex,
54	            List<Integer> traversalOrder) {
55	        Deque<Integer> pendingVertices = new ArrayDeque<>();
56	        pendingVertices.push(startVertex);
57	
58	        while (!pendingVertices.isEmpty()) {
59	            int vertex = pendingVertices.pop();
60	            if (visitedVertices[vertex]) {
61	                continue;
62	            }
63	
64	            visitedVertices[vertex] = true;
65	            traversalOrder.add(vertex);
66	
67	            List<Integer> neighbors = adjacencyList.get(vertex);
68	            for (int index = neighbors.size() - 1; index >= 0; index--) {
69	                int neighbor = neighbors.get(index);
70	                if (!visitedVertices[neighbor]) {
71	                    pendingVertices.push(neighbor);
72	                }
73	            }
74	        }
75	    }
